begin;
create temp table domain_fixture as select user_id u,partner_user_id p,gen_random_uuid() a,gen_random_uuid() b,gen_random_uuid() x,gen_random_uuid() investment,gen_random_uuid() debt,gen_random_uuid() flow from partner_links where status='active' limit 1;
grant select on domain_fixture to authenticated;
insert into accounts(id,user_id,name,type,currency,current_balance) select a,u,'Domain planning fixture','checking','USD',1000 from domain_fixture union all select b,p,'Partner planning fixture','checking','USD',1000 from domain_fixture;
insert into transactions(id,user_id,account_id,name,date,amount,category) select x,u,a,'Payroll fixture','2026-01-31',-1000,'Salary' from domain_fixture;
insert into accounts(id,user_id,name,type,currency,current_balance) select investment,u,'Investment fixture','investment','USD',2000 from domain_fixture union all select debt,u,'Debt fixture','credit','USD',1000 from domain_fixture;
insert into transactions(id,user_id,account_id,name,date,amount,category) select flow,u,investment,'External contribution fixture','2026-01-31',-100,'Transfer' from domain_fixture;
set local role authenticated;
do $$declare f record;p jsonb;r jsonb;again jsonb;rid uuid;request uuid:=gen_random_uuid();blocked boolean;begin
 select * into strict f from domain_fixture;perform set_config('request.jwt.claim.role','authenticated',true);perform set_config('request.jwt.claim.sub',f.u::text,true);
 p:=jsonb_build_object('date','2026-01-31','periodStart','2026-01-01','periodEnd','2026-01-15','currency','USD','salary',1200,'bonus',0,'otherCash',0,'taxes',200,'retirement',0,'benefits',0,'deductions',0,'reimbursements',0,'employerRetirement',100,'equity',200,'transactionIds',jsonb_build_array(f.x));
 r:=finance_save_module_record('income','paycheck','Fixture',p,null,null,'active',request);rid:=(r->>'id')::uuid;
 again:=finance_save_module_record('income','paycheck','Fixture',p,null,null,'active',request);if again<>r then raise exception 'Idempotency replay changed result';end if;
 if (select count(*) from finance_module_record_history where record_id=rid)<>1 then raise exception 'Replay duplicated audit';end if;
 blocked:=false;begin perform finance_save_module_record('income','paycheck','Different',p,null,null,'active',request);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Reused request accepted altered payload';end if;
 blocked:=false;begin perform finance_save_module_record('income','paycheck','Duplicate',p,null,null,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Deposit double counted';end if;
 blocked:=false;begin perform finance_save_module_record('income','paycheck','Invalid',jsonb_set(p,'{salary}','"1200"'),null,null,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Malformed numeric accepted';end if;
 perform finance_save_module_record('income','paycheck','Revised',p,rid,1,'active',gen_random_uuid());
 blocked:=false;begin perform finance_save_module_record('income','paycheck','Stale',p,rid,1,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Stale revision overwritten';end if;
 perform finance_save_module_record('income','paycheck','Revised',p,rid,2,'archived',gen_random_uuid());
 if (select count(*) from finance_module_record_history where record_id=rid)<>3 then raise exception 'Archive lost history';end if;
 blocked:=false;begin delete from finance_module_records where id=rid;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Planning history could be deleted';end if;
 blocked:=false;begin update finance_module_records set name='Bypass' where id=rid;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Direct write bypassed audit';end if;
 p:=jsonb_build_object('date','2026-01-31','currency','USD','accountId',f.investment,'symbol','FIXTURE','assetClass','Stocks','units',10,'price',100,'costBasis',800,'feeBps',20);
 perform finance_save_module_record('investments','holding','Fixture holding',p,null,null,'active',gen_random_uuid());
 blocked:=false;begin perform finance_save_module_record('investments','holding','Duplicate holding',p,null,null,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Same position double counted';end if;
 p:=jsonb_build_object('date','2026-01-31','currency','USD','accountId',f.investment,'value',2000);
 perform finance_save_module_record('investments','valuation','Fixture valuation',p,null,null,'active',gen_random_uuid());
 blocked:=false;begin perform finance_save_module_record('investments','valuation','Duplicate valuation',p,null,null,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Duplicate valuation accepted';end if;
 p:=jsonb_build_object('date','2026-01-31','currency','USD','accountId',f.investment,'amount',100,'transactionIds',jsonb_build_array(f.flow));
 perform finance_save_module_record('investments','flow','Fixture contribution',p,null,null,'active',gen_random_uuid());
 blocked:=false;begin perform finance_save_module_record('investments','flow','Duplicate contribution',p,null,null,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Same flow counted twice';end if;
 p:=jsonb_build_object('date','2026-01-31','currency','USD','accountId',f.debt,'apr',20,'minimum',30,'minimumPct',0,'promoApr',0,'promoEnd','2026-07-01');
 perform finance_save_module_record('debt','terms','Fixture debt',p,null,null,'active',gen_random_uuid());
 blocked:=false;begin perform finance_save_module_record('debt','terms','Duplicate terms',p,null,null,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Duplicate debt terms accepted';end if;
 blocked:=false;begin perform finance_save_module_record('debt','terms','Wrong account',jsonb_set(p,'{accountId}',to_jsonb(f.b::text)),null,null,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Partner account reference accepted';end if;
 p:='{"date":"2026-01-31","currency":"USD","startingAssets":1000,"monthlySaving":100,"savingGrowth":0,"years":30,"inflation":2.5,"downside":-5,"base":0,"upside":5,"annualSpending":0,"scope":"Private snapshot","events":[{"name":"Home","date":"2027-01-01","amount":-200}]}';
 perform finance_save_module_record('long_term','scenario','Fixture life plan',p,null,null,'active',gen_random_uuid());
 blocked:=false;begin perform finance_save_module_record('long_term','scenario','Past event',jsonb_set(p,'{events,0,date}','"2025-01-01"'),null,null,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Past event replayed as future';end if;
 select payload into p from finance_module_records where id=rid;
 perform set_config('request.jwt.claim.sub',f.p::text,true);
 if exists(select 1 from finance_module_records where id=rid) or exists(select 1 from finance_module_record_history where record_id=rid) then raise exception 'Partner read private planning';end if;
 blocked:=false;begin perform finance_save_module_record('income','paycheck','Partner',p,rid,3,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Partner edited owner record';end if;
 blocked:=false;begin perform finance_save_module_record('income','paycheck','Partner deposit',p,null,null,'active',gen_random_uuid());exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Partner linked private deposit';end if;
end;$$;
reset role;
do $$begin if (select amount from transactions where id=(select x from domain_fixture))<>-1000 then raise exception 'Canonical transaction changed';end if;end;$$;
set local role anon;
do $$declare blocked boolean:=false;begin begin perform finance_save_module_record('income','paycheck','Anonymous','{}',null,null,'active',gen_random_uuid());exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Anonymous planning allowed';end if;end;$$;
reset role;rollback;
select 'PASS: all four domains save; unique positions, valuations, debt terms and source flows; owner isolation, private history, authenticated mutation only, unchanged transactions, revision conflicts, idempotent retries and duplicate deposit rejection. All fixtures rolled back.' as result;
